"use client";

import { CheckCircle2, Loader2, Lock } from "lucide-react";
import Link from "next/link";
import { useState, type FormEvent } from "react";

import { ImageUploader } from "@/components/ui/image-uploader";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";

type StoryForm = {
  authorName: string;
  authorEmail: string;
  authorUniversity: string;
  authorBatch: string;
  yearOfSelection: string;
  achievement: string;
  quote: string;
  fullStory: string;
  authorPhotoUrl: string;
  authorPhotoPublicId: string;
};

const emptyForm: StoryForm = {
  authorName: "",
  authorEmail: "",
  authorUniversity: "",
  authorBatch: "",
  yearOfSelection: "",
  achievement: "",
  quote: "",
  fullStory: "",
  authorPhotoUrl: "",
  authorPhotoPublicId: "",
};

export function ShareYourStory() {
  const [form, setForm] = useState<StoryForm>(emptyForm);
  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState<string | null>(null);

  function update<Key extends keyof StoryForm>(
    key: Key,
    value: StoryForm[Key],
  ) {
    setForm((current) => ({ ...current, [key]: value }));
  }

  function reset() {
    setForm(emptyForm);
    setError("");
    setSubmitted(false);
  }

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError("");

    if (
      !form.authorName.trim() ||
      !form.authorEmail.trim() ||
      !form.authorUniversity.trim() ||
      !form.authorBatch.trim() ||
      !form.achievement.trim() ||
      !form.quote.trim()
    ) {
      setError("Complete all required fields before submitting.");
      return;
    }

    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.authorEmail.trim())) {
      setError("Enter a valid email address.");
      return;
    }

    if (form.quote.trim().length < 10) {
      setError("Your quote must be at least 10 characters.");
      return;
    }

    if (form.achievement.trim().length < 2) {
      setError("Achievement must be at least 2 characters.");
      return;
    }

    if (form.yearOfSelection) {
      const year = Number(form.yearOfSelection);

      if (!/^\d{4}$/.test(form.yearOfSelection) || year < 1990 || year > 2100) {
        setError("Enter a four-digit selection year between 1990 and 2100.");
        return;
      }
    }

    setLoading(true);

    const payload = {
      authorName: form.authorName.trim(),
      authorEmail: form.authorEmail.trim(),
      authorUniversity: form.authorUniversity.trim(),
      authorBatch: form.authorBatch.trim(),
      achievement: form.achievement.trim(),
      quote: form.quote.trim(),
      fullStory: form.fullStory.trim() || undefined,
      yearOfSelection: form.yearOfSelection
        ? Number(form.yearOfSelection)
        : undefined,
      authorPhotoUrl: form.authorPhotoUrl || undefined,
      authorPhotoPublicId: form.authorPhotoPublicId || undefined,
    };

    try {
      const response = await fetch("/api/success-stories", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      const result = (await response.json()) as { error?: string };

      if (response.status !== 201) {
        throw new Error(result.error ?? "Unable to submit your story.");
      }

      setSubmitted(true);
      setForm(emptyForm);
    } catch (caughtError) {
      setError(
        caughtError instanceof Error
          ? caughtError.message
          : "Unable to submit your story. Please try again.",
      );
    } finally {
      setLoading(false);
    }
  }

  return (
    <section className="border-t border-border bg-cream px-6 py-20 lg:py-24">
      <div className="mx-auto grid max-w-6xl items-start gap-12 lg:grid-cols-12 lg:gap-16">
        <div className="lg:col-span-5">
          <p className="text-xs font-semibold uppercase tracking-[0.25em] text-accent">
            YOUR STORY
          </p>
          <h2 className="mt-4 max-w-md font-heading text-3xl font-bold leading-tight text-primary lg:text-4xl">
            Did you clear the exam? Share your journey.
          </h2>
          <p className="mt-5 max-w-md text-base leading-7 text-muted">
            Your story could be the reason someone else keeps going. Submit it
            and we&apos;ll review it before publishing.
          </p>

          <div className="mt-8">
            <h3 className="text-[13px] font-semibold uppercase tracking-widest text-primary">
              What to include
            </h3>
            <ul className="mt-4 flex flex-col gap-3">
              {[
                "Your name and university",
                "Your batch and year of selection",
                "A short quote about your preparation",
                "Optionally, a longer write-up",
              ].map((item) => (
                <li key={item} className="flex items-start gap-3">
                  <CheckCircle2
                    aria-hidden="true"
                    size={16}
                    className="mt-0.5 shrink-0 text-accent"
                  />
                  <span className="text-sm leading-6 text-muted">{item}</span>
                </li>
              ))}
            </ul>
          </div>

          <p className="mt-10 flex items-center gap-2 text-sm text-muted">
            <Lock aria-hidden="true" size={15} className="text-accent" />
            We never publish your email address.
          </p>
        </div>

        <div className="lg:col-span-7">
          <Card className="border border-border bg-card p-6 shadow-sm lg:p-10">
            {submitted ? (
              <div className="flex min-h-[480px] flex-col items-center justify-center py-12 text-center">
                <CheckCircle2
                  aria-hidden="true"
                  size={48}
                  className="mx-auto text-accent"
                />
                <h3 className="mt-6 font-heading text-xl font-bold text-primary">
                  Thank you.
                </h3>
                <p className="mx-auto mt-3 max-w-md text-[15px] leading-7 text-muted">
                  Your story has been submitted for review. We&apos;ll publish
                  it once approved.
                </p>
                <div className="mt-6 flex flex-wrap justify-center gap-3">
                  <button
                    type="button"
                    onClick={reset}
                    className="h-10 cursor-pointer rounded-md px-4 text-sm text-muted hover:bg-primary/5 hover:text-primary"
                  >
                    Submit another story
                  </button>
                  <Link
                    href="/success-stories"
                    className="inline-flex h-10 cursor-pointer items-center rounded-md border border-border px-4 text-sm text-primary hover:bg-primary/5"
                  >
                    Back to stories
                  </Link>
                </div>
              </div>
            ) : (
              <form onSubmit={submit} className="flex flex-col gap-8">
                <header>
                  <h3 className="font-heading text-xl font-semibold text-primary">
                    Submit your story
                  </h3>
                  <p className="mt-1 text-sm text-muted">
                    All fields marked with * are required.
                  </p>
                </header>

                <section>
                  <h4 className="text-[13px] font-medium uppercase tracking-wide text-muted">
                    Photo (optional)
                  </h4>
                  <div className="mt-3">
                    <ImageUploader
                      value={form.authorPhotoUrl || null}
                      publicId={form.authorPhotoPublicId || null}
                      onChange={(image) => {
                        update("authorPhotoUrl", image.url ?? "");
                        update("authorPhotoPublicId", image.publicId ?? "");
                      }}
                      folder="bjs-prep/success-stories"
                      aspect="square"
                      size={96}
                      helperText="JPEG, PNG, or WebP. Max 5 MB."
                    />
                  </div>
                </section>

                <section>
                  <h4 className="text-[13px] font-medium uppercase tracking-wide text-muted">
                    About you
                  </h4>
                  <div className="mt-3 grid gap-5 sm:grid-cols-2">
                    <Field
                      id="story-author-name"
                      label="Full name *"
                      required
                      autoComplete="name"
                      maxLength={120}
                      value={form.authorName}
                      onChange={(value) => update("authorName", value)}
                    />
                    <Field
                      id="story-author-email"
                      label="Email *"
                      required
                      type="email"
                      autoComplete="email"
                      value={form.authorEmail}
                      onChange={(value) => update("authorEmail", value)}
                    />
                    <Field
                      id="story-university"
                      label="University *"
                      required
                      maxLength={160}
                      value={form.authorUniversity}
                      onChange={(value) => update("authorUniversity", value)}
                    />
                    <Field
                      id="story-batch"
                      label="Batch *"
                      required
                      maxLength={40}
                      placeholder="e.g. 2019-20"
                      value={form.authorBatch}
                      onChange={(value) => update("authorBatch", value)}
                    />
                    <Field
                      id="story-selection-year"
                      label="Year of selection"
                      type="number"
                      min={1990}
                      max={2100}
                      placeholder="e.g. 2024"
                      value={form.yearOfSelection}
                      onChange={(value) => update("yearOfSelection", value)}
                    />
                    <Field
                      id="story-achievement"
                      label="Achievement *"
                      required
                      maxLength={200}
                      placeholder="e.g. Selected as Assistant Judge"
                      value={form.achievement}
                      onChange={(value) => update("achievement", value)}
                    />
                  </div>
                </section>

                <section>
                  <h4 className="text-[13px] font-medium uppercase tracking-wide text-muted">
                    Your story
                  </h4>
                  <div className="mt-3 flex flex-col gap-6">
                    <label
                      htmlFor="story-quote"
                      className="block text-sm font-medium text-foreground"
                    >
                      Short quote *
                      <Textarea
                        id="story-quote"
                        required
                        rows={4}
                        minLength={10}
                        maxLength={500}
                        value={form.quote}
                        onChange={(event) =>
                          update("quote", event.target.value)
                        }
                        className="mt-2"
                      />
                      <span className="mt-1 block text-right text-xs font-normal text-muted">
                        {form.quote.length} / 500
                      </span>
                    </label>

                    <label
                      htmlFor="story-full-story"
                      className="block text-sm font-medium text-foreground"
                    >
                      Full story{" "}
                      <span className="font-normal text-muted">(optional)</span>
                      <Textarea
                        id="story-full-story"
                        rows={8}
                        maxLength={5000}
                        value={form.fullStory}
                        onChange={(event) =>
                          update("fullStory", event.target.value)
                        }
                        className="mt-2"
                      />
                      <span className="mt-1 block text-right text-xs font-normal text-muted">
                        {form.fullStory.length} / 5000
                      </span>
                    </label>
                  </div>
                </section>

                {error ? (
                  <p role="alert" className="text-sm text-red-600">
                    {error}
                  </p>
                ) : null}

                <button
                  type="submit"
                  disabled={loading}
                  className="h-12 w-full cursor-pointer rounded-md bg-primary font-medium text-cream hover:bg-primary-dark disabled:cursor-not-allowed disabled:opacity-60"
                >
                  {loading ? (
                    <span className="inline-flex items-center justify-center gap-2">
                      <Loader2 size={17} className="animate-spin" />
                      Submitting...
                    </span>
                  ) : (
                    "Submit story"
                  )}
                </button>
                <p className="-mt-5 text-center text-xs text-muted">
                  By submitting, you agree that we may publish your story with
                  your name and university.
                </p>
              </form>
            )}
          </Card>
        </div>
      </div>
    </section>
  );
}

function Field({
  id,
  label,
  value,
  onChange,
  ...inputProps
}: {
  id: string;
  label: string;
  value: string;
  onChange: (value: string) => void;
} & Omit<
  React.InputHTMLAttributes<HTMLInputElement>,
  "id" | "value" | "onChange"
>) {
  return (
    <label htmlFor={id} className="block text-sm font-medium text-primary">
      {label}
      <Input
        id={id}
        value={value}
        onChange={(event) => onChange(event.target.value)}
        className="mt-2"
        {...inputProps}
      />
    </label>
  );
}
